    for n in nums:
        if n > best:
            best = n
    return best

def collatz_steps(n: int) -> int:
    steps: int = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps = steps + 1
    return steps

def balanced_parens(s: str) -> bool:
    depth: int = 0
    for c in s:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def longest_run(nums: list[int]) -> int:
    best: int = 0
    cur: int = 0
    prev: int = 0
    for i in range(len(nums)):
        if i == 0 or nums[i] == prev:
            cur += 1
        else:
            cur = 1
        prev = nums[i]
        if cur > best:
            best = cur
    return best

def merge_sorted(a: list[int], b: list[int]) -> list[int]:
    result: list[int] = []
    i: int = 0
    j: int = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    while i < len(a):
        result.append(a[i])
        i += 1
    while j < len(b):
        result.append(b[j])
        j += 1
    return result

def remove_duplicates(nums: list[int]) -> list[int]:
    seen: set[int] = set()
    result: list[int] = []
    for n in nums:
        if n not in seen:
            seen.add(n)
            result.append(n)
    return result

def caesar_shift(s: str, k: int) -> str:
    res: str = ""
    for c in s:
        if 'a' <= c <= 'z':
            res += chr(ord('a') + (ord(c) - ord('a') + k) % 26)
        else:
            res += c
    return res

def to_binary(n: int) -> str:
    if n == 0:
        return "0"
    bits: list[str] = []
    while n > 0:
        bits.append(chr(ord("0") + n % 2))
        n = n // 2
    return "".join(bits[::-1])

def digit_sum(n: int) -> int:
    total: int = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total

def two_sum(nums: list[int], target: int) -> list[int]:
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [i, j]
    return [-1, -1]

def max_subarray_sum(nums: list[int]) -> int:
    best: int = nums[0]
    cur: int = nums[0]
    for i in range(1, len(nums)):
        x: int = nums[i]
        cur = x if cur + x < x else cur + x
        if cur > best:
            best = cur
    return best

def prime_factors(n: int) -> list[int]:
    factors: list[int] = []
    d: int = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n = n // d
        d = d + 1
    if n > 1:
        factors.append(n)
    return factors

