def capitalize_words(s: str) -> str:
    result = ""
    capitalize_next = True
    for ch in s:
        if ch == " ":
            result += ch
            capitalize_next = True
        elif capitalize_next:
            if "a" <= ch <= "z":
                result += chr(ord(ch) - 32)
            else:
                result += ch
            capitalize_next = False
        else:
            result += ch
    return result

def longest_common_prefix(words: list[str]) -> str:
    if len(words) == 0:
        return ""
    prefix: str = words[0]
    for w in words:
        n: int = min(len(prefix), len(w))
        i: int = 0
        while i < n and prefix[i] == w[i]:
            i = i + 1
        prefix = prefix[:i]
    return prefix

def rotate_left(nums: list[int], k: int) -> list[int]:
    n: int = len(nums)
    if n == 0:
        return []
    k = k % n
    return nums[k:] + nums[:k]

def fizz_buzz(n: int) -> list[str]:
