def is_anagram(a: str, b: str) -> bool:
    if len(a) != len(b):
        return False
    counts_a: dict[str, int] = {}
    counts_b: dict[str, int] = {}
    for ch in a:
        counts_a[ch] = counts_a.get(ch, 0) + 1
    for ch in b:
        counts_b[ch] = counts_b.get(ch, 0) + 1
    for ch in counts_a:
        if counts_a[ch] != counts_b.get(ch, 0):
            return False
    return True

def second_largest(nums: list[int]) -> int:
    distinct: list[int] = []
    for n in nums:
        if n not in distinct:
            distinct.append(n)
    if len(distinct) < 2:
        return -1
    distinct.sort()
    return distinct[len(distinct) - 2]

def pascal_row(n: int) -> list[int]:
    row: list[int] = [1]
    for _ in range(n):
        new: list[int] = [1]
        for i in range(len(row) - 1):
            new.append(row[i] + row[i + 1])
        new.append(1)
        row = new
    return row

def greatest_common_divisor(a: int, b: int) -> int:
    while b > 0:
        a, b = b, a % b
    return a

def most_frequent(nums: list[int]) -> int:
    counts: dict[int, int] = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1
    best: int = nums[0]
    best_count: int = counts[best]
    for n in nums:
        c: int = counts[n]
        if c > best_count or (c == best_count and n < best):
            best = n
            best_count = c
    return best

