def count_inversions(nums: list[int]) -> int:
    def merge_count(a: list[int], b: list[int]) -> tuple[list[int], int]:
        merged: list[int] = []
        count: int = 0
        i: int = 0
        j: int = 0
        while i < len(a) and j < len(b):
            if a[i] <= b[j]:
                merged.append(a[i])
                i += 1
            else:
                merged.append(b[j])
                j += 1
                count += len(a) - i
        while i < len(a):
            merged.append(a[i])
            i += 1
        while j < len(b):
            merged.append(b[j])
            j += 1
        return (merged, count)

    def sort_count(a: list[int]) -> tuple[list[int], int]:
        n: int = len(a)
        if n <= 1:
            return (a, 0)
        mid: int = n // 2
        left, cl = sort_count(a[:mid])
        right, cr = sort_count(a[mid:])
        merged, cm = merge_count(left, right)
        return (merged, cl + cr + cm)

    return sort_count(nums)[1]

def to_hex(n: int) -> str:
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result: str = ""
    while n > 0:
        result = digits[n % 16] + result
        n = n // 16
    return result

def integer_sqrt(n: int) -> int:
    lo: int = 0
    hi: int = n
    while lo < hi:
        mid: int = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def interleave(a: list[int], b: list[int]) -> list[int]:
    result: list[int] = []
    n: int = min(len(a), len(b))
    for i in range(n):
        result.append(a[i])
        result.append(b[i])
    for i in range(n, len(a)):
        result.append(a[i])
    for i in range(n, len(b)):
        result.append(b[i])
    return result

def char_code_sum(s: str) -> int:
    total: int = 0
    for c in s:
        total += ord(c)
    return total

def join_uppercase(words: list[str], sep: str) -> str:
    result: str = ""
    for i, w in enumerate(words):
        if i > 0:
            result += sep
        for c in w:
            result += chr(ord(c) - 32)
    return result

def best_profit(prices: list[int]) -> int:
    best: int = 0
    lowest: int = prices[0]
    for p in prices:
        if p < lowest:
            lowest = p
        elif p - lowest > best:
            best = p - lowest
    return best

def missing_number(nums: list[int]) -> int:
    n: int = len(nums)
    total: int = n * (n + 1) // 2
    return total - sum(nums)

def count_words(s: str) -> int:
    count: int = 0
    in_word: bool = False
    for ch in s:
        if ch != ' ':
            if not in_word:
                count += 1
                in_word = True
        else:
            in_word = False
    return count

def all_unique(nums: list[int]) -> bool:
    seen: set[int] = set()
    for n in nums:
        if n in seen:
            return False
        seen.add(n)
    return True

def clamp_values(nums: list[int], lo: int, hi: int) -> list[int]:
    result: list[int] = []
    for n in nums:
        if n < lo:
            result.append(lo)
        elif n > hi:
            result.append(hi)
        else:
            result.append(n)
    return result

def string_repeat(s: str, n: int) -> str:
    result: str = ""
    for _ in range(n):
        result += s
    return result

def power_mod(base: int, exp: int, m: int) -> int:
    b: int = base % m
    r: int = 1 % m
    e: int = exp
    while e > 0:
        if e % 2 == 1:
            r = (r * b) % m
        b = (b * b) % m
        e = e // 2
    return r

def last_index_of(nums: list[int], target: int) -> int:
    result: int = -1
    for i in range(len(nums)):
        if nums[i] == target:
            result = i
    return result

def strip_digits(s: str) -> str:
    res: str = ""
    for c in s:
        if not ('0' <= c <= '9'):
            res += c
    return res

def pairwise_differences(nums: list[int]) -> list[int]:
    result: list[int] = []
    for i in range(len(nums) - 1):
        result.append(nums[i + 1] - nums[i])
    return result

def longest_word(words: list[str]) -> str:
    best: str = words[0]
    for w in words:
        if len(w) > len(best):
            best = w
    return best

def count_char(s: str, ch: str) -> int:
    count: int = 0
    for c in s:
        if c == ch:
            count += 1
    return count

def triangle_kind(a: int, b: int, c: int) -> str:
    if a + b <= c or a + c <= b or b + c <= a:
        return "invalid"
    if a == b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"

def dot_product(a: list[int], b: list[int]) -> int:
    total: int = 0
    for i in range(len(a)):
        total += a[i] * b[i]
    return total

def swap_case(s: str) -> str:
    result: str = ""
    for c in s:
        o: int = ord(c)
        if 97 <= o <= 122:
            result += chr(o - 32)
        elif 65 <= o <= 90:
            result += chr(o + 32)
        else:
            result += c
    return result
